create table xxcus.xxcmp_request_answers (
    answer_id             number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by
    1 cache 20 noorder nocycle nokeep noscale not null enable,
    request_id            number not null enable,
    case_id               number,
    respondent_type       varchar2(30 byte) not null enable,
    question_id           number not null enable,
    answer_option_id      number,
    answer_text           varchar2(4000 byte),
    risk_points           number,
    created_by            varchar2(255 byte) not null enable,
    creation_date         timestamp(6) not null enable,
    last_updated_by       varchar2(255 byte) not null enable,
    last_update_date      timestamp(6) not null enable,
    last_update_login     varchar2(255 byte),
    object_version_number number default 1 not null enable
);

alter table xxcus.xxcmp_request_answers
    add constraint xxcmp_request_answers_ck1
        check ( respondent_type in ( 'REQUESTER', 'OFFICER' ) ) enable;

alter table xxcus.xxcmp_request_answers
    add constraint xxcmp_request_answers_pk primary key ( answer_id )
        using index enable;

alter table xxcus.xxcmp_request_answers
    add constraint xxcmp_request_answers_uk1
        unique ( request_id,
                 respondent_type,
                 question_id )
            using index enable;


